import functools

def _parse(version):
    main_and_pre = version.split('+', 1)[0]
    if '-' in main_and_pre:
        main, pre = main_and_pre.split('-', 1)
    else:
        main, pre = main_and_pre, None
    parts = main.split('.')
    major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])
    pre_ids = pre.split('.') if pre is not None else None
    return major, minor, patch, pre_ids

def _compare_identifier(a, b):
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        ai, bi = int(a), int(b)
        if ai < bi:
            return -1
        elif ai > bi:
            return 1
        else:
            return 0
    elif a_num and not b_num:
        return -1
    elif not a_num and b_num:
        return 1
    else:
        if a < b:
            return -1
        elif a > b:
            return 1
        else:
            return 0

def _compare(v1, v2):
    major1, minor1, patch1, pre1 = _parse(v1)
    major2, minor2, patch2, pre2 = _parse(v2)

    if major1 != major2:
        return -1 if major1 < major2 else 1
    if minor1 != minor2:
        return -1 if minor1 < minor2 else 1
    if patch1 != patch2:
        return -1 if patch1 < patch2 else 1

    if pre1 is None and pre2 is None:
        return 0
    if pre1 is None and pre2 is not None:
        return 1
    if pre1 is not None and pre2 is None:
        return -1

    for a, b in zip(pre1, pre2):
        c = _compare_identifier(a, b)
        if c != 0:
            return c

    if len(pre1) != len(pre2):
        return -1 if len(pre1) < len(pre2) else 1

    return 0

def semver_sort(versions):
    return sorted(versions, key=functools.cmp_to_key(_compare))

